PRAGMA defer_foreign_keys=TRUE;
CREATE TABLE memories (id INTEGER PRIMARY KEY AUTOINCREMENT,created_at INTEGER NOT NULL,kind TEXT NOT NULL DEFAULT 'episodic',content TEXT NOT NULL,importance REAL NOT NULL DEFAULT 0.5,source TEXT NOT NULL DEFAULT 'chat',metadata TEXT NOT NULL DEFAULT '{}', fingerprint TEXT);
CREATE TABLE interactions (id INTEGER PRIMARY KEY AUTOINCREMENT,created_at INTEGER NOT NULL,user_text TEXT NOT NULL,assistant_text TEXT NOT NULL,model TEXT NOT NULL,feedback INTEGER,correction TEXT);
CREATE TABLE memories_v021_snapshot(
  id INT,
  created_at INT,
  kind TEXT,
  content TEXT,
  importance REAL,
  source TEXT,
  metadata TEXT
);
CREATE TABLE memory_migrations (version TEXT PRIMARY KEY,applied_at INTEGER NOT NULL,before_count INTEGER NOT NULL,duplicate_count INTEGER NOT NULL,after_count INTEGER NOT NULL,bookmark TEXT,notes TEXT);
DELETE FROM sqlite_sequence;
CREATE INDEX idx_memories_created ON memories(created_at DESC);
CREATE INDEX idx_memories_kind ON memories(kind);
CREATE INDEX idx_interactions_created ON interactions(created_at DESC);
CREATE UNIQUE INDEX idx_memories_fingerprint ON memories(fingerprint) WHERE fingerprint IS NOT NULL;
